-- =====================================================================
-- 校园失物招领智能匹配与AI图像识别系统 - 数据库初始化脚本
-- 说明：密码统一为 123456（BCrypt 加密存储）
-- =====================================================================
--
-- 【重要警告】本脚本会「删除并重建所有表」，执行后原有数据将全部清空！
--   仅用于【首次部署】或【需要重置数据】时执行一次。
--   日常重启系统（重启 MySQL / 后端 / 前端）无需、也不要再执行本脚本：
--   MySQL 数据已持久化在磁盘，直接启动各服务即可，数据不会丢失。
--
-- =====================================================================
CREATE DATABASE IF NOT EXISTS lost_found DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE lost_found;

-- 清空旧表（按依赖顺序）
DROP TABLE IF EXISTS t_chat_message;
DROP TABLE IF EXISTS t_subscription;
DROP TABLE IF EXISTS t_claim_record;
DROP TABLE IF EXISTS t_notification;
DROP TABLE IF EXISTS t_match_record;
DROP TABLE IF EXISTS t_post;
DROP TABLE IF EXISTS t_user;

-- 用户表
CREATE TABLE t_user (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键',
    username    VARCHAR(50)  NOT NULL UNIQUE COMMENT '用户名',
    password    VARCHAR(100) NOT NULL COMMENT '密码（BCrypt）',
    nickname    VARCHAR(50)  DEFAULT NULL COMMENT '昵称',
    role        VARCHAR(20)  NOT NULL DEFAULT 'USER' COMMENT '角色：USER/ADMIN',
    avatar      VARCHAR(255) DEFAULT NULL COMMENT '头像',
    phone       VARCHAR(20)  DEFAULT NULL COMMENT '手机号',
    email       VARCHAR(100) DEFAULT NULL COMMENT '邮箱',
    status      TINYINT      NOT NULL DEFAULT 0 COMMENT '0正常 1已注销（禁用登录）',
    create_time DATETIME     DEFAULT NULL COMMENT '注册时间'
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='用户表';

-- 帖子表（失物 / 招领）
CREATE TABLE t_post (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键',
    user_id        BIGINT       NOT NULL COMMENT '发布者ID',
    type           VARCHAR(10)  NOT NULL COMMENT 'LOST失物 / FOUND招领',
    title          VARCHAR(100) NOT NULL COMMENT '物品名称',
    category       VARCHAR(50)  DEFAULT NULL COMMENT '物品类别',
    location       VARCHAR(100) DEFAULT NULL COMMENT '丢失/拾获地点',
    lost_time      DATETIME     DEFAULT NULL COMMENT '丢失/拾获时间',
    description    TEXT COMMENT '详细描述',
    image_urls     VARCHAR(1000) DEFAULT NULL COMMENT '图片相对路径（逗号分隔）',
    feature_vector TEXT COMMENT 'AI图像特征向量（960维，逗号分隔浮点）',
    status         TINYINT      NOT NULL DEFAULT 0 COMMENT '0展示中 1已认领归档 2已下架 3待审核 4审核未通过',
    ai_category    VARCHAR(50)  DEFAULT NULL COMMENT 'AI自动识别类别',
    ocr_key        VARCHAR(64)  DEFAULT NULL COMMENT 'OCR提取的关键号码（学号/卡号），用于精确匹配',
    text_vector    TEXT         DEFAULT NULL COMMENT '文本语义向量（Chinese-CLIP文本塔，与图像同空间）',
    image_caption  VARCHAR(255) DEFAULT NULL COMMENT '首图中文描述（BLIP+英译中），用于匹配详情悬浮展示',
    ai_audit_result VARCHAR(20) DEFAULT NULL COMMENT 'AI初审核结论 PASS/WARN/REJECT',
    ai_audit_note   VARCHAR(500) DEFAULT NULL COMMENT 'AI初审核说明（风险点描述）',
    audit_reason    VARCHAR(255) DEFAULT NULL COMMENT '人工审核拒绝原因',
    create_time    DATETIME     DEFAULT NULL COMMENT '发布时间',
    update_time    DATETIME     DEFAULT NULL COMMENT '更新时间',
    KEY idx_user (user_id),
    KEY idx_type_status (type, status),
    KEY idx_category (category),
    KEY idx_location (location)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='帖子表';

-- 匹配记录表
CREATE TABLE t_match_record (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键',
    lost_post_id  BIGINT      NOT NULL COMMENT '失物帖ID',
    found_post_id BIGINT      NOT NULL COMMENT '招领帖ID',
    text_score    DOUBLE      DEFAULT NULL COMMENT '纯文字匹配分(0~1)',
    image_score   DOUBLE      DEFAULT NULL COMMENT '图像相似度(0~1)',
    score         DOUBLE      DEFAULT NULL COMMENT '综合匹配分(0~1)',
    status        VARCHAR(20) NOT NULL DEFAULT 'NEW' COMMENT 'NEW/CONTACTED/CLAIMED/IGNORED',
    create_time   DATETIME    DEFAULT NULL COMMENT '匹配时间',
    UNIQUE KEY uk_pair (lost_post_id, found_post_id),
    KEY idx_lost (lost_post_id),
    KEY idx_found (found_post_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='匹配记录表';

-- 通知表
CREATE TABLE t_notification (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键',
    user_id     BIGINT       NOT NULL COMMENT '接收用户ID',
    type        VARCHAR(20)  NOT NULL COMMENT 'MATCH/CLAIM/SYSTEM',
    title       VARCHAR(100) DEFAULT NULL COMMENT '标题',
    content     VARCHAR(500) DEFAULT NULL COMMENT '内容',
    related_id  BIGINT       DEFAULT NULL COMMENT '关联的匹配记录/帖子ID',
    extra_id    BIGINT       DEFAULT NULL COMMENT '额外关联ID（一键联系时我的帖子ID）',
    is_read     TINYINT      NOT NULL DEFAULT 0 COMMENT '0未读 1已读',
    create_time DATETIME     DEFAULT NULL COMMENT '时间',
    KEY idx_user_read (user_id, is_read)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='通知表';

-- 私聊消息表
CREATE TABLE t_chat_message (
    id              BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键',
    conversation_id VARCHAR(64)  NOT NULL COMMENT '会话ID（用户对+帖子三元组，如 2_3_34，无帖子记 0）',
    sender_id       BIGINT       NOT NULL COMMENT '发送者ID',
    receiver_id     BIGINT       NOT NULL COMMENT '接收者ID',
    content         VARCHAR(500) NOT NULL COMMENT '消息内容',
    post_id         BIGINT       DEFAULT NULL COMMENT '关联帖子ID（会话上下文，可空）',
    is_read         TINYINT      NOT NULL DEFAULT 0 COMMENT '0未读 1已读',
    create_time     DATETIME     DEFAULT NULL COMMENT '发送时间',
    KEY idx_conversation (conversation_id, create_time),
    KEY idx_receiver (receiver_id, is_read)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='私聊消息表';

-- 认领记录表
CREATE TABLE t_claim_record (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键',
    match_id    BIGINT       NOT NULL COMMENT '匹配记录ID',
    post_id     BIGINT       NOT NULL COMMENT '被认领的失物帖ID',
    claimant_id BIGINT       NOT NULL COMMENT '申请人（失主）ID',
    message     VARCHAR(500) DEFAULT NULL COMMENT '认领说明',
    status      VARCHAR(20)  NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING/CONFIRMED/REJECTED',
    create_time DATETIME     DEFAULT NULL COMMENT '申请时间',
    KEY idx_match (match_id),
    KEY idx_claimant (claimant_id),
    KEY idx_post (post_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='认领记录表';

-- 订阅表（主动触达：用户订阅某类型/类别/地点的帖子，新帖子发布时推送提醒）
CREATE TABLE t_subscription (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '主键',
    user_id     BIGINT       NOT NULL COMMENT '订阅用户ID',
    type        VARCHAR(10)  NOT NULL COMMENT '订阅的帖子类型 LOST/FOUND',
    category    VARCHAR(50)  DEFAULT NULL COMMENT '订阅类别（空=全部）',
    location    VARCHAR(100) DEFAULT NULL COMMENT '订阅地点关键词（空=全部）',
    create_time DATETIME     DEFAULT NULL COMMENT '订阅时间',
    KEY idx_user (user_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT ='订阅表';

